import{_ as n,a0 as s,w as p,s as l,ao as m,I as r,x as i,a1 as t,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"7個殺手級的開源監測工具 | LCTT x X-CMD","titleTemplate":false,"description":"7個殺手級的開源監測工具 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7個殺手級的開源監測工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7個殺手級的開源監測工具 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140924 7 killer open source monitoring tools","title":"7個殺手級的開源監測工具","tag":"201411","desc":""},"relativePath":"201411/20140924 7 killer open source monitoring tools.md","filePath":"[post].md"}'),g={name:"201411/20140924 7 killer open source monitoring tools.md"};function d(h,e,b,c,u,x){const a=s("Link");return p(),l("div",null,[e[13]||(e[13]=m('<h1 id="_7個殺手級的開源監測工具" tabindex="-1">7個殺手級的開源監測工具 <a class="header-anchor" href="#_7個殺手級的開源監測工具" aria-label="Permalink to “7個殺手級的開源監測工具”">​</a></h1><p>想要更清晰的瞭解你的網絡嗎？沒有比這幾個免費的工具更好用的了。</p><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_01-netmon-intro-100448913-gallery.idge.jpg" alt=""></p><p>網絡和系統監控是一個很寬的範疇。有監控服務器、網絡設備、應用正常工作的方案，也有跟蹤這些系統和設備性能，提供趨勢性能分析的解決方案。有些工具像個鬧鐘一樣，當發現問題的時候就會報警，而另外的一些工具甚至可以在警報響起的時候觸發一些動作。這裏，收集了一些開源的工具，旨在解決上述的一些甚至大部分問題。</p><h3 id="cacti" tabindex="-1">Cacti <a class="header-anchor" href="#cacti" aria-label="Permalink to “Cacti”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_02-netmon-cacti-100448914-orig.jpg" alt=""></p><p>Cacti是一個性能廣泛的圖表和趨勢分析工具，可以用來跟蹤並幾乎可以繪製出任何可監測指標，描繪出圖表。從硬盤的利用率到風扇的轉速，在一個電腦管理系統中，只要是可以被監測的指標，Cacti都可以監測，並快速的轉換成可視化的圖表。</p><h3 id="nagios" tabindex="-1">Nagios <a class="header-anchor" href="#nagios" aria-label="Permalink to “Nagios”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_03-netmon-nagios-100448915-orig.jpg" alt=""></p><p>Nagios是一個經典的老牌系統和網絡監測工具。運行速度快，可靠，需要針對應用定製。Nagios對於初學者是一個挑戰。但是它的極其複雜的配置正好也反應出它的強大，因為它幾乎可以適用於任何監控任務。要説缺點的話就是不怎麼耐看，但是其強勁的功能和可靠性彌補了這個缺點。</p><h3 id="icinga" tabindex="-1">Icinga <a class="header-anchor" href="#icinga" aria-label="Permalink to “Icinga”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_04-netmon-icinga-100448916-orig.jpg" alt=""></p><p>Icinga 是一個正在重建的Nagios的分支，它提供了一個全面的監控和警報的框架，致力於設計一個像Nagios一樣的開放和可擴展性的平台。但是和Nagios擁有不一樣的Web界面。Icinga 1 和 Nagios非常的相近，不過Icinga 2就重寫了。兩個版本都能很好的兼容，而且，Nagios用户可以很輕鬆的轉到Icinga 1平台。</p><h3 id="nedi" tabindex="-1">NeDi <a class="header-anchor" href="#nedi" aria-label="Permalink to “NeDi”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_05-netmon-nedi-100448917-orig.jpg" alt=""></p><p>NeDi可能不如其他的工具一樣聞名全世界，但它確是一個跟蹤網絡接入的一個強大的解決方案。它可以很流暢的運行網絡基礎設施和設備目錄，保持對任何事件的跟蹤。並且可以提供任意設備的當前地點，也包括歷史地點。</p><p>NeDi可以被用於定位被偷的，或者是丟失掉的設備，只要設備出現在網絡上。它甚至可以在地圖上顯示所有已發現的節點。並且很清晰的告訴人們網絡是怎麼互聯的到物理設備端口的。</p><h3 id="observium" tabindex="-1">Observium <a class="header-anchor" href="#observium" aria-label="Permalink to “Observium”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_06-netmon-observium-100448918-orig.jpg" alt=""></p><p>Observium 綜合了系統和網路監控，在性能趨勢監測上有很好的表現，它支持靜態和動態發現來確認服務器和網絡設備，利用多種監測方法，可以監測任何可用的指標。Web界面非常的整潔，易用。</p><p>就如我們看到的，Observium也可以在地圖上顯示任何被監測節點的實際地點。需要注意的是面板上關於活躍設備和警報的計數。</p><h3 id="zabbix" tabindex="-1">Zabbix <a class="header-anchor" href="#zabbix" aria-label="Permalink to “Zabbix”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_07-netmon-zabbix-100448919-orig.jpg" alt=""></p><p>Zabbix 利用一系列的工具監測服務器和網絡。Zabbix的監控代理支持大多數的操作系統，你可以被動的或者是使用外部檢查，包括SNMP來監控主機和網絡設備。你也會發現很多提醒和通知設施，和一個非常人性化的Web界面，適用於不同的面板，此外，Zabbix還擁有一些特殊的管理工具來監測Web應用和虛擬化的管理程序。</p><p>Zabbix 還可以提供詳細的互聯圖，以便於我們瞭解某些對象是怎麼連接的。這些圖是可以定製的，並且，圖也可以以被監測的服務器和主機的分組形式被創建。</p><h3 id="ntop" tabindex="-1">Ntop <a class="header-anchor" href="#ntop" aria-label="Permalink to “Ntop”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_08-netmon-ntop-100448920-orig.jpg" alt=""></p><p>Ntop是一個數據包嗅探工具。有一個整潔的Web界面，用來顯示被監測網絡的實時數據。即時的網絡數據通過一個高級的繪圖工具可以可視化。主機數據流和與之對應的主機通信信息可以被實時的進行可視化顯示。</p><hr>',29)),r("p",null,[e[1]||(e[1]=i("via: ",-1)),t(a,{href:"http://www.networkworld.com/article/2686794/asset-management/164219-7-killer-open-source-monitoring-tools.html"},{default:o(()=>[...e[0]||(e[0]=[i("http://www.networkworld.com/article/2686794/asset-management/164219-7-killer-open-source-monitoring-tools.html",-1)])]),_:1})]),r("p",null,[e[5]||(e[5]=i("作者：",-1)),t(a,{href:"http://www.networkworld.com/author/Paul-Venezia/"},{default:o(()=>[...e[2]||(e[2]=[i("Paul Venezia",-1)])]),_:1}),e[6]||(e[6]=i(" 譯者：",-1)),t(a,{href:"https://github.com/barney-ro"},{default:o(()=>[...e[3]||(e[3]=[i("barney-ro",-1)])]),_:1}),e[7]||(e[7]=i(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=i("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原創翻譯，",-1)),t(a,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[i("Linux中國",-1)])]),_:1}),e[12]||(e[12]=i(" 榮譽推出",-1))])])}const k=n(g,[["render",d]]);export{T as __pageData,k as default};
